"""Pydantic models for request validation and response serialization.

Every request body and response body in the API is described by one of the
models below — this is the enforced "contract" the course describes (Meeting
5A/5B): the Backend validates that incoming JSON has the required fields, types,
and now also safe character/length limits, before any of it reaches the
database.
"""

import re
from typing import Optional

from pydantic import BaseModel, Field, field_validator


# --------------------------------------------------------------------------- #
# Authentication
# --------------------------------------------------------------------------- #
class UserCreate(BaseModel):
    """Incoming payload for registration and login.

    [SECURITY HARDENING] L-1: ``username`` is restricted to a safe character set
    (letters, digits, ``_ . -``) and 3–50 chars; the password must be at least 6
    chars. This is server-side input validation (Meeting 5B) — it rejects empty,
    over-long, or control-character input before it ever reaches the database.
    """

    username: str = Field(..., min_length=3, max_length=50, pattern=r"^[A-Za-z0-9_.-]+$")
    password: str = Field(..., min_length=6, max_length=128)


class Token(BaseModel):
    """Response returned by ``POST /auth/login``."""

    access_token: str
    token_type: str = "bearer"


class UserOut(BaseModel):
    """Public representation of a user (never includes the password hash)."""

    id: int
    username: str
    created_at: str


# --------------------------------------------------------------------------- #
# Messages
# --------------------------------------------------------------------------- #
class MessageCreate(BaseModel):
    """Incoming payload for ``POST /messages``.

    A message belongs to exactly one channel:
    * ``group_id is None`` and ``recipient_username is None`` → public chat,
    * ``group_id`` set → that group,
    * ``recipient_username`` set → a 1-to-1 direct message to that user.

    (The route rejects sending both ``group_id`` and ``recipient_username``.)
    """

    content: str = Field(..., min_length=1, max_length=2000)
    group_id: Optional[int] = None
    recipient_username: Optional[str] = Field(
        default=None, max_length=50, pattern=r"^[A-Za-z0-9_.-]+$"
    )


class MessageEdit(BaseModel):
    """[FEATURE] Incoming payload for ``PATCH /messages/{id}`` (edit own message)."""

    content: str = Field(..., min_length=1, max_length=2000)


class TypingPing(BaseModel):
    """[FEATURE] Incoming payload for ``POST /typing`` (typing indicator).

    Scope is one channel: a ``group_id`` (public when None) or a DM ``peer``.
    """

    group_id: Optional[int] = None
    peer: Optional[str] = Field(default=None, max_length=50, pattern=r"^[A-Za-z0-9_.-]+$")


class MessageOut(BaseModel):
    """A single message as returned to the client."""

    id: int
    sender_username: str
    content: str
    timestamp: str
    group_id: Optional[int] = None
    recipient_username: Optional[str] = None
    file_name: Optional[str] = None
    file_type: Optional[str] = None
    # [FEATURE] edit/delete markers + DM read-receipt state.
    edited: bool = False
    is_deleted: bool = False
    seen: bool = False  # for DMs: True once the recipient has read this message


# --------------------------------------------------------------------------- #
# Group chats
# --------------------------------------------------------------------------- #
_USERNAME_PATTERN = re.compile(r"^[A-Za-z0-9_.-]{3,50}$")


class GroupCreate(BaseModel):
    """Incoming payload for ``POST /groups``.

    [FEATURE] PRIVATE GROUPS: ``members`` is the list of usernames invited into
    the group at creation. The group is invite-only — only the creator plus these
    members can see it (``GET /groups`` lists a user's groups only) and read/post
    in it (the membership Authorization check, Meeting 4A). An empty list makes a
    group only the creator belongs to.
    """

    name: str = Field(..., min_length=1, max_length=80)
    members: list[str] = Field(default_factory=list, max_length=200)

    @field_validator("name")
    @classmethod
    def _clean_name(cls, v: str) -> str:
        """[SECURITY HARDENING] L-1: trim and reject blank/control-char names."""
        v = v.strip()
        if not v:
            raise ValueError("Group name cannot be empty")
        if any(ord(c) < 32 for c in v):
            raise ValueError("Group name contains invalid characters")
        return v

    @field_validator("members")
    @classmethod
    def _clean_members(cls, v: list[str]) -> list[str]:
        """[FEATURE] De-duplicate and validate each invited username (same safe
        charset/length as registration). Existence is checked in the route."""
        out: list[str] = []
        seen: set[str] = set()
        for raw in v:
            u = (raw or "").strip()
            if not u or u in seen:
                continue
            if not _USERNAME_PATTERN.match(u):
                raise ValueError("Invalid member username")
            seen.add(u)
            out.append(u)
        return out


class GroupOut(BaseModel):
    """A group chat as returned to the client."""

    id: int
    name: str
    created_at: str
